57	export default function Movimentacoes() {
58	  const [movements, setMovements] = useState<Movement[]>([]);
59	  const [isLoading, setIsLoading] = useState(true);
60	  const [sectorFilter, setSectorFilter] = useState<string>("todos");
61	  const [userFilter, setUserFilter] = useState<string>("todos");
62	  const [sectors, setSectors] = useState<string[]>([]);
63	  const [productSearch, setProductSearch] = useState<string>("");
64	  const { hasData, applyStoreFilter, storeId } = useStoreFilter();
65	  const { canViewEstoque, hasPermission, isAdmin } = usePermissions();
66	
67	  const isMobile = useIsMobile();
68	  const { theme, setTheme } = useTheme();
69	  const navigate = useNavigate();
70	  const { userProfile, user, signOut } = useAuth();
71	  const [serverVersion, setServerVersion] = useState<string | null>(null);
72	  const [currentPage, setCurrentPage] = useState(1);
73	  const ITEMS_PER_PAGE = 20;
74	
75	  useMiaMovimentacoesActions({
76	    setSectorFilter,
77	    setProductSearch,
78	    setCurrentPage,
79	    movements,
80	  });
81	
82	  useEffect(() => {
83	    if (hasData) {
84	      fetchSectors();
85	      fetchMovements();
86	    }
87	  }, [hasData, storeId]);
88	
89	  useEffect(() => {
90	    setCurrentPage(1);
91	  }, [sectorFilter, productSearch, userFilter]);
92	
93	  useEffect(() => {
94	    fetchMovements();
95	  }, [currentPage, sectorFilter, storeId, hasData, productSearch]);
96	
97	  useEffect(() => {
98	    if (isMobile) {
99	      fetch(`/version.json?t=${Date.now()}`)
100	        .then(res => res.json())
101	        .then(data => setServerVersion(data.version))
102	        .catch(err => console.error("Failed to fetch server version", err));
103	    }
104	  }, [isMobile]);
105	
106	  const fetchSectors = async () => {
107	    try {
108	      if (!hasData) {
109	        setSectors([]);
110	        return;
111	      }
112	
113	      // Use standard view for sectors
114	      // @ts-expect-error - supabase view type not in generated types
115	      const query = supabase
116	        .from('vw_produtos_estoque_lojas')
117	        .select('setor')
118	        .eq('loja_id', storeId) // Explicitly filter by store
119	        .not('setor', 'is', null);
120	
121	      const { data, error } = await query;
122	
123	      if (error) throw error;
124	
125	      const uniqueSectors = [...new Set(data?.map((p: any) => p.setor) || [])]
126	        .filter(sector => sector && sector.toLowerCase() !== 'compras');
127	      setSectors(uniqueSectors as string[]);
128	    } catch (error) {
129	      console.error('Erro ao carregar setores:', error);
130	    }
131	  };
132	
133	  const fetchMovements = async () => {
134	    try {
135	      if (!hasData) {
136	        setMovements([]);
137	        return;
138	      }
139	
140	      const from = (currentPage - 1) * ITEMS_PER_PAGE;
141	      const to = from + ITEMS_PER_PAGE - 1;
142	
143	      // If there's a product search, prioritize it - search ALL movements without pagination
144	      if (productSearch.trim()) {
145	        const term = productSearch.trim();
146	        let searchQuery = supabase
147	          .from('view_movimentacoes_recentes')
148	          .select('*')
149	          .or(`produto_nome.ilike.%${term}%,codigo_interno_str.ilike.%${term}%,lote_codigo.ilike.%${term}%`)
150	          .order('data_movimentacao', { ascending: false })

150	          .order('data_movimentacao', { ascending: false })
151	          .limit(500); // High limit to get comprehensive results for the search
152	
153	        searchQuery = applyStoreFilter(searchQuery);
154	        const { data: searchData, error: searchError } = await searchQuery;
155	
156	        if (searchError) throw searchError;
157	        setMovements(searchData || []);
158	        return;
159	      }
160	
161	      if (sectorFilter !== "todos") {
162	        // Buscar produtos do setor - uses standard view
163	        // @ts-expect-error - supabase view type not in generated types
164	        const produtosQuery = supabase
165	          .from('vw_produtos_estoque_lojas')
166	          .select('produto_master_id, nome')
167	          .eq('loja_id', storeId)
168	          .eq('setor', sectorFilter);
169	
170	        const { data: produtos, error: produtosError } = await produtosQuery;
171	
172	        if (produtosError) throw produtosError;
173	
174	        if (produtos && produtos.length > 0) {
175	          const produtoNomes = produtos.map((p: any) => p.nome);
176	
177	          // Buscar movimentações filtrando pelo nome do produto
178	          let movQuery = supabase
179	            .from('view_movimentacoes_recentes')
180	            .select('*')
181	            .in('produto_nome', produtoNomes)
182	            .order('data_movimentacao', { ascending: false })
183	            .range(from, to);
184	
185	          movQuery = applyStoreFilter(movQuery);
186	          const { data: movData, error: movError } = await movQuery;
187	
188	          if (movError) throw movError;
189	          setMovements(movData || []);
190	        } else {
191	          setMovements([]);
192	        }
193	      } else {
194	        // Buscar todas as movimentações
195	        let allMovQuery = supabase
196	          .from('view_movimentacoes_recentes')
197	          .select('*')
198	          .order('data_movimentacao', { ascending: false })
199	          .range(from, to);
200	
201	        allMovQuery = applyStoreFilter(allMovQuery);
202	        const { data: allMovData, error: allMovError } = await allMovQuery;
203	
204	        if (allMovError) throw allMovError;
205	        setMovements(allMovData || []);
206	      }
207	    } catch (error) {
208	      console.error('Erro ao carregar movimentações:', error);
209	      toast({
210	        title: "Erro",
211	        description: "Não foi possível carregar as movimentações",
212	        variant: "destructive",
213	      });
214	    } finally {
215	      setIsLoading(false);
216	    }
217	  };
218	
219	  const getMovementColor = (type: string) => {
220	    return type === 'entrada' ? 'text-green-600' : 'text-red-600';
221	  };
222	
223	  const formatMovementType = (type: string) => {
224	    if (type === 'entrada') return 'Entrada';
225	    if (type === 'saida') return 'Saída';
226	    if (type === 'perda') return 'Perda';
227	    if (type === 'mudanca_categoria') return 'Mudança de categoria';
228	    if (type === 'cadastro') return 'Cadastro';
229	    if (type === 'exclusao') return 'Exclusão';
230	    return type;
231	  };
232	
233	  const uniqueUsers = [...new Set(movements.map(m => m.usuario_nome))].filter(Boolean).sort();
234	  const filteredMovements = userFilter === 'todos' ? movements : movements.filter(m => m.usuario_nome === userFilter);
235	
236	  if (isLoading) {
237	    return (
238	      <div className="flex items-center justify-center min-h-screen">
239	        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
240	      </div>
241	    );
242	  }
243	
244	  const hasAccess = hasPermission("view_movimentacoes") || canViewEstoque() || isAdmin();
245	
246	  if (isMobile) {
247	    return (
248	      <PermissionBlur hasPermission={hasAccess} moduleName="Estoque" permissionName="view_movimentacoes">
249	        <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans">
250	          {/* Store Awning Stripe Effect (Top Border) */}
251	          <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
252	
253	          {/* Animated Plant Background Elements */}
254	          <div className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: '10s' }}>
255	            <Leaf className="w-full h-full text-[#57715B] rotate-12" />
256	          </div>
257	
258	          {/* Header */}
259	          <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
260	            <div className="flex items-center gap-3">
261	              <Button variant="ghost" size="icon" onClick={() => navigate(-1)} className="h-10 w-10 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10">
262	                <ArrowLeft className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
263	              </Button>
264	              <h1 className="text-xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Movimentações</h1>
265	            </div>
266	            <div className="flex items-center gap-2">
267	              {/* Profile Menu with Store Selector and Theme Toggle */}
268	              <DropdownMenu>
269	                <DropdownMenuTrigger asChild>
270	                  <Button variant="ghost" className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative">
271	                    <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
272	                      <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
273	                        {(user?.user_metadata?.nome || "U").slice(0, 2).toUpperCase()}
274	                      </AvatarFallback>
275	                    </Avatar>
276	                  </Button>
277	                </DropdownMenuTrigger>
278	                <DropdownMenuContent className="w-64 rounded-2xl border-[#E6DCCF] dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl" align="end" sideOffset={8}>
279	                  <DropdownMenuLabel className="font-normal p-4">
280	                    <div className="flex flex-col space-y-1">
281	                      <p className="text-base font-semibold leading-none text-[#57715B] dark:text-zinc-100">{user?.user_metadata?.nome || userProfile?.nome}</p>
282	                      <p className="text-xs text-zinc-500">{user?.email}</p>
283	                    </div>
284	                  </DropdownMenuLabel>
285	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
286	
287	                  {/* Store Selector inside Profile */}
288	                  <div className="px-2 py-2">
289	                    <div className="text-xs font-semibold text-muted-foreground px-2 mb-2">Loja</div>
290	                    <StoreSelector />
291	                  </div>
292	
293	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
294	
295	                  {/* Theme Toggle inside Profile */}
296	                  <div className="px-2 py-2 flex items-center justify-between">
297	                    <span className="text-sm font-medium px-2">Tema</span>
298	                    <Button
299	                      variant="ghost"
300	                      size="sm"
301	                      onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
302	                      className="h-8 w-8 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
303	                    >
304	                      <Sun className="h-4 w-4 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
305	                      <Moon className="absolute h-4 w-4 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
306	                    </Button>
307	                  </div>
308	
309	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
310	
311	                  {/* Version Indicator */}
312	                  <div className="px-2 py-1.5 text-[10px] text-center text-zinc-400 select-none">
313	                    v{String(typeof __APP_VERSION__ !== 'undefined' ? __APP_VERSION__ : '1.0.0')} / srv {serverVersion || '...'}
314	                  </div>
315	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
